import sys


def main():
    deps = {}
    seen = set()
    for line in sys.stdin:
        if not line.strip():
            continue
        name, _, rest = line.partition(":")
        name = name.strip()
        deps.setdefault(name, []).extend([dep.strip() for dep in rest.split()])

    def visit(task):
        if task in seen:
            return False
        seen.add(task)
        for d in sorted(deps.get(task, [])):
            if visit(d):
                return True
        seen.remove(task)
        order.append(task)
        return False

    order = []
    for task in sorted(deps):
        if visit(task):
            print("CYCLE: " + " ".join(sorted(seen)))
            return

    for task in order:
        print(task)


if __name__ == "__main__":
    main()
